commit 6a872565cbdc3aa55449eb220658152b18355505
Author: Checkout POC <dev@example.com>
Date:   Sat Oct 24 23:36:08 2026 +0530

    Add discountType to coupons (regresses on legacy coupons)

    October 2026 migration: coupons now carry a discountType ('PERCENTAGE' |
    'FIXED') so we can support fixed dollar-off coupons. calculateDiscount now
    reads coupon.discountType.

    Regression: legacy coupons created before the migration have no discountType,
    so calculateDiscount throws a TypeError for them. The test suite still passes
    because it only covers new coupons. See src/reproduceLegacyBug.ts.

diff --git a/src/checkout/discountService.ts b/src/checkout/discountService.ts
index da61eef..1a00724 100644
--- a/src/checkout/discountService.ts
+++ b/src/checkout/discountService.ts
@@ -4,13 +4,24 @@ import { logger } from '../logger';
 /**
  * Translate a coupon into an absolute discount amount for a given subtotal.
  *
- * At this stage every coupon is a simple percentage-off coupon.
+ * Coupons can be either PERCENTAGE or FIXED. The discount type was introduced
+ * in the October 2026 migration; every coupon written after the migration
+ * carries a `discountType`.
  */
 export function calculateDiscount(subtotal: number, coupon: Coupon): number {
   logger.info('Calculating discount', { code: coupon.code, subtotal });

-  const discount = subtotal * (coupon.percentOff / 100);
+  // NOTE: this assumes every coupon has a discountType. Coupons created before
+  // the migration do not, so this line throws for legacy data.
+  const normalizedType = coupon.discountType.toUpperCase();

-  logger.info('Discount calculated', { code: coupon.code, discount });
+  let discount: number;
+  if (normalizedType === 'PERCENTAGE') {
+    discount = subtotal * (coupon.amount / 100);
+  } else {
+    discount = Math.min(coupon.amount, subtotal);
+  }
+
+  logger.info('Discount calculated', { code: coupon.code, type: normalizedType, discount });
   return discount;
 }
